Once we've started the conversation, we start a new thread to read the messages. Our third
method reads the messages in an endless loop:
private async Task ReadBotMessagesAsync(DirectLineClient client, string
conversationId)
{
string watermark = string.Empty;
var messages = new List<KeyValuePair<string, string>>();
while (true)
{
var activitySet = await
client.Conversations.GetActivitiesAsync(conversationId, watermark);
lock (_lock)
{
watermark = activitySet.Watermark;
var activities = from x in activitySet.Activities
select x;
messages.Clear();
foreach (Activity activity in activities)
{
messages.Add(new KeyValuePair<string,
